ALTER TABLE "affiliate_applications" DROP CONSTRAINT "affiliate_applications_content_check";--> statement-breakpoint
ALTER TABLE "affiliate_applications" ALTER COLUMN "channel_url" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "affiliate_applications" ALTER COLUMN "audience" DROP NOT NULL;--> statement-breakpoint
ALTER TABLE "affiliate_applications" ADD COLUMN IF NOT EXISTS "whatsapp_phone" varchar(32);--> statement-breakpoint
ALTER TABLE "affiliate_applications" ADD COLUMN IF NOT EXISTS "social_media" text;--> statement-breakpoint
ALTER TABLE "affiliate_applications" ADD CONSTRAINT "affiliate_applications_content_check" CHECK (("affiliate_applications"."channel_url" IS NULL OR length(btrim("affiliate_applications"."channel_url")) BETWEEN 8 AND 512) AND ("affiliate_applications"."audience" IS NULL OR length(btrim("affiliate_applications"."audience")) BETWEEN 2 AND 4000) AND length(btrim("affiliate_applications"."promotion_plan")) BETWEEN 2 AND 4000 AND ("affiliate_applications"."whatsapp_phone" IS NULL OR "affiliate_applications"."whatsapp_phone" ~ '^\+[1-9][0-9]{6,14}$') AND ("affiliate_applications"."social_media" IS NULL OR length("affiliate_applications"."social_media") <= 2000));
